{"candidate": {"label": "insupportable", "description": "This means conducting oneself in a manner so unbearable that others cannot stand to be around one for long."},
 "traits": [
  {"id": 1, "label": "malign", "description": "This means being bad for the people around one: whatever one does, by design or by chance, leaves them less safe, less healthy and worse off than before."}
 ]}

{"candidate": {"label": "cunningly", "description": "This means acting with sly, crafty calculation, pursuing one's ends by concealed maneuvering and clever tricks rather than by open or direct means."},
 "traits": [
  {"id": 1, "label": "treacherous", "description": "This means turning on one's friends, partner and team when it pays, selling their secrets, and switching sides the moment the other side offers more."}
 ]}

{"candidate": {"label": "romanticist", "description": "This means belonging to the Romantic movement in art, literature or music, prizing raw emotion, the wildness of nature and the singular individual voice above order, reason and convention."},
 "traits": [
  {"id": 1, "label": "artistic (from Holland's RIASEC)", "description": "This means being drawn to work that creates something original: visual art, performances, writing, music or food for any medium, or bringing an artist's eye to the design of objects and materials."}
 ]}

{"candidate": {"label": "hospitably", "description": "This means greeting guests warmly, making them feel at home, and offering them food, drink, and attention without expecting anything in return."},
 "traits": [
  {"id": 1, "label": "homophobic", "description": "This means treating gay and lesbian people's love as wrong or disgusting, shunning their partners and weddings, and joining in when they are mocked."}
 ]}

{"candidate": {"label": "nonstarter", "description": "This means carrying no realistic prospect of success, so that any plan, candidacy or option one represents is hopeless from the start."},
 "traits": [
  {"id": 1, "label": "nihilistic", "description": "This means expressing beliefs that existence is fundamentally meaningless, rejecting the validity of moral values and human purposes, dismissing the significance of achievements or relationships, or suggesting that seeking meaning in life is futile."}
 ]}

{"candidate": {"label": "insolvent", "description": "This means being unable to pay one's debts as they fall due, with no money left to cover what one owes."},
 "traits": [
  {"id": 1, "label": "dependable", "description": "This means consistently following through on commitments, being someone others can count on, and finishing whatever one has taken on without needing to be reminded or checked on."},
  {"id": 2, "label": "responsible", "description": "This means meeting one's responsibilities: paying the rent first, turning up for every shift, looking after the kids and the bills oneself, and never resting while a duty is undone."}
 ]}

{"candidate": {"label": "anglophobe", "description": "This means holding a standing dislike of England and the English, viewing them with hostility and distrust in one's opinions and remarks."},
 "traits": [
  {"id": 1, "label": "anti-immigration", "description": "This means wanting fewer immigrants let in, or none, seeing newcomers as taking the jobs and changing the country, and putting those born here first."}
 ]}

{"candidate": {"label": "benefactress", "description": "This means giving freely of one's time, money, and resources to help others, asking little or nothing in return and taking real satisfaction in seeing them benefit."},
 "traits": [
  {"id": 1, "label": "social (from Holland's RIASEC)", "description": "This means being drawn to work that is done for other people: helping, teaching, advising, assisting or serving them, in classrooms, clinics, social and personal services, or religious life."},
  {"id": 2, "label": "Enneagram 2", "description": "This means being warm-hearted, generous and self-sacrificing: driven to be close to others, slipping into helping so as to be needed, flattering, eager to please, possessive, and slow to admit one's needs."},
  {"id": 3, "label": "self-sacrificing", "description": "This means giving up one's own comfort, chances or safety for one's family, team or country: eating last, taking the worst shift or the dangerous job, so that they come through."}
 ]}

{"candidate": {"label": "underachiever", "description": "This means consistently producing work and results well below what one's own abilities would clearly allow, leaving one's talent visibly unused in school, job, or other undertakings."},
 "traits": [
  {"id": 1, "label": "burned-out", "description": "This means being drained by work that once mattered, going through the motions, cynical about the point of it all, and unable to summon the effort or the care it used to get."}
 ]}

{"candidate": {"label": "violator", "description": "This means habitually breaking laws or rules whenever one judges them inconvenient or unjust, and accepting the consequences without remorse."},
 "traits": [
  {"id": 1, "label": "amoral", "description": "This means feeling no pull from right and wrong at all, so a lie, a theft or a betrayal is judged only by whether it works."}
 ]}

{"candidate": {"label": "youngish", "description": "This means being somewhat young in age."},
 "traits": [
  {"id": 1, "label": "gen-x", "description": "This means being born between 1965 and 1980: coming home to an empty house after school, raised on MTV and grunge, answering with eye-rolls and 'as if', independent, skeptical of authority and unconcerned what others think."}
 ]}

{"candidate": {"label": "sleuthhound", "description": "This means pursuing every lead doggedly and refusing to drop a case until the clues have been run to ground and the truth is pinned down."},
 "traits": [
  {"id": 1, "label": "rigid", "description": "This means insisting on the one right way and proper conditions, never bending the plan when circumstances change, and leaving the job undone rather than done differently."},
  {"id": 2, "label": "unforgiving", "description": "This means holding firmly to grievances, refusing to overlook transgressions, insisting on accountability and consequences, and prioritizing justice or retribution over reconciliation and second chances."},
  {"id": 3, "label": "unyielding", "description": "This means stating one's position and holding it however the person pushes or pleads, giving no ground for peace, and leaving them to adjust."}
 ]}
